import React, { useMemo, useState } from "react";
import { Button, Card, Modal, Table, TableProps, Input, TableColumnProps, Space, Message } from "@arco-design/web-react";
import { JSONSchemaCustom, SchemaApiJsonPage, SchemaQueryForm, SchemaTable } from "@/components/schema";
import Store from './store';
import _ from 'lodash';
import language from "@/store/language";
import { useObserver } from "mobx-react-lite";
import utils from "utils";
import { IconDelete, IconPlus } from "@arco-design/web-react/icon";
import app from "@/store/app";
import { AsyncButton } from "@/components/custom";
import { isPermission } from "@/components/Permission/utils";

const Index = () => {

    const [store] = useState(() => {
        return new Store();
    })
    




    return useObserver(() => {

        const schema = useMemo(() => {

            return {
                type: "object",
                properties: {
                    "languekey": {
                        "title": "多语言Key",
                        columnProps: {
                            width: 160,
                            fixed: "left",
                            ellipsis: true,
                        }
                    },
                    ...store.options.reduce((objs, item) => {
                        return {
                            ...objs,
                            [item.value.replace('-', '')]: {
                                title: item.label,
                                columnProps: {
                                    ellipsis: true,
                                    width: 150,
                                }
                            }
                        }
                    },{}),
                    updatedAt: {
                        title: "更新时间",
                        columnProps: {
                            width: 180,
                        }
                    }
                }
            } as JSONSchemaCustom;
        },[store.options])

        const columns = useMemo(() => {

            return [
                {
                    title: "多语言Key",
                    dataIndex: "languekey",
                    bodyCellStyle: {
                        padding: 2,
                    },
                    fixed: "left",
                    width: 180,
                    render: store.type == 'edit'? undefined : (col, item, index) => {
                        return (
                            <Input
                                value={col}
                                onChange={(val) => {
                                    store.changeValue(index, 'languekey', val);
                                }}
                            />
                        )
                    }
                },
                ...store.options.map((o) => {
                    const field = o.value.replace('-', '')
                    return {
                        title: o.label,
                        dataIndex: field,
                        width: 180,
                        fixed: o.value == 'zh-CN'? "left" : undefined,
                        bodyCellStyle: {
                            padding: 2,
                        },
                        render: (col, item, index) => {
                            return (
                                <Input
                                    value={col}
                                    onChange={(val) => {
                                        store.changeValue(index, field, val);
                                    }}
                                />
                            )
                        }
                    } as TableColumnProps;
                }),
                {
                    title: "设置",
                    fixed: "right",
                    width: 100,
                    render: (col, item, index) => {
                        return (
                            <Button
                                onClick={() => {
                                    store.deleteIndex(index)
                                }}
                                icon={
                                    <IconDelete />
                                }
                            ></Button>
                        )
                    }
                }
            ] as TableProps['columns']
        },[store.type, store.options])
        

        const { selectedRowKeys, setSelectedRowKeys } = store;


        return (
            <React.Fragment>
                <SchemaApiJsonPage
                    ref={store.pageRef}
                    apijson={{
                        tableName: "Language",
                        uniqueKey: "id",
                        notAdd: true,
                        findParams: {
                            "@order": "updatedAt-"
                        }
                    }}
                    schemaTable={{
                        rowKey: "id",
                        rowSelection: {
                            selectedRowKeys: selectedRowKeys,
                            onChange: (keys) => {
                                setSelectedRowKeys(keys);
                            }
                        },
                        toolBarRender: [
                            <Button
                                type="primary"
                                onClick={() => {
                                    store.setType('add')
                                }}
                            >
                                新增多语言
                            </Button>,
                            <Button type="primary" disabled={!selectedRowKeys.length} 
                                onClick={() => {
                                    store.onUpdateList();
                                }}
                            >
                                更新多语言
                            </Button>,
                            <Button type="primary"
                                onClick={() => {
                                    store.setLangVisible(true);
                                    store.setSelectKeys(_.cloneDeep(app.extraInfo.languageKeys));
                                }}
                            >
                                多语言管理
                            </Button>
                        ]
                    }}
                    schema={schema}
                    queryFilterKeys={['languekey', 'zhCN', 'enUS']}
                />
                <Modal
                    title={store.title}
                    style={{
                        width: 1200
                    }}
                    visible={Boolean(store.type)}
                    onCancel={() => {
                        store.setType('');
                    }}
                    onOk={() => {
                        store.submit();
                    }}
                >
                    <div className="flex justify-end">
                        <Space className="mb-4">
                            {store.type == 'add'? (
                                <Button type="primary" icon={<IconPlus />}
                                    onClick={() => {
                                        store.setList([
                                            ...store.list,
                                            { key: Math.random().toString(36).slice(2) },
                                        ])
                                    }}
                                >
                                    新增
                                </Button>
                            ): null}
                            {isPermission('sys.role.admin')? (
                                <AsyncButton type="primary"
                                    onClick={() => {
                                        return store.changeAiCompletion();
                                    }}
                                >
                                    AI补全
                                </AsyncButton>
                            ): null}
                        </Space>
                    </div>
                    <Table
                        rowKey={"key"}
                        pagination={false}
                        scroll={{
                            x: true,
                            y: true,
                        }}
                        columns={columns}
                        data={store.list}
                    />
                </Modal>
                <Modal
                    title="多语言管理"
                    visible={store.langVisible}
                    onCancel={() => {
                        store.setLangVisible(false)
                    }}
                    onOk={async () => {
                        app.assignExtraInfo({
                            languageKeys: store.selectKeys,
                        })
                        return app.savaExtraInfo().then(() => {
                            store.setLangVisible(false)
                            Message.success("多语言修改成功")
                        });
                    }}
                >
                    <Table
                        rowKey="value"
                        data={language.options}
                        pagination={false}
                        columns={[
                            {
                                title: "多语言名称",
                                dataIndex: "label"
                            },
                            {
                                title: "多语言值",
                                dataIndex: "value"
                            }
                        ]}
                        rowSelection={{
                            selectedRowKeys: store.selectKeys,
                            onChange: store.setSelectKeys,
                        }}
                    />
                </Modal>
            </React.Fragment>
        )
    })
}


export default Index;